using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    /// <summary>
    /// Helper to safely call DropDownControl.
    /// .NET 9: IWindowsFormsEditorService.DropDownControl now throws ArgumentNullException if control is null.
    /// </summary>
    public static void SafeDropDown(IWindowsFormsEditorService editorService, Control? control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }

    /// <summary>
    /// .NET 9: StatusStrip default rendering changed. Explicitly set Professional renderer
    /// to preserve the previous visual behavior.
    /// </summary>
    public static StatusStrip CreateStatusStrip()
    {
        var strip = new StatusStrip();
        strip.RenderMode = ToolStripRenderMode.Professional;
        return strip;
    }
}

